package es.vargontoc.storyteller.infrastructure.config;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
import org.springframework.ai.ollama.api.OllamaApi;
import org.springframework.web.client.RestClient;
class CharacterModelProvisionerTest {
 @Test void existingModelDoesNotCreateAgain(){OllamaApi api=mock(OllamaApi.class);OllamaApi.Model model=mock(OllamaApi.Model.class);when(model.name()).thenReturn("storyteller-character:latest");when(api.listModels()).thenReturn(new OllamaApi.ListModelResponse(List.of(model)));new CharacterModelProvisioner(api,"http://localhost:11434","storyteller-character","qwen2.5:14b-instruct","safe").run(mock(org.springframework.boot.ApplicationArguments.class));verify(api).listModels();}
 @Test void missingModelCreatesWithCurrentOllamaBody(){OllamaApi api=mock(OllamaApi.class);when(api.listModels()).thenReturn(new OllamaApi.ListModelResponse(List.of()));RestClient client=mock(RestClient.class);RestClient.RequestBodyUriSpec request=mock(RestClient.RequestBodyUriSpec.class);RestClient.RequestBodySpec body=mock(RestClient.RequestBodySpec.class);RestClient.ResponseSpec response=mock(RestClient.ResponseSpec.class);when(client.post()).thenReturn(request);when(request.uri("/api/create")).thenReturn(request);when(request.contentType(any())).thenReturn(request);when(request.body(any(Object.class))).thenReturn(body);when(body.retrieve()).thenReturn(response);new CharacterModelProvisioner(api,client,"storyteller-character","base-model","system text").run(mock(org.springframework.boot.ApplicationArguments.class));verify(request).body(Map.of("model","storyteller-character","from","base-model","system","system text","stream",false));verify(response).toBodilessEntity();}
 @Test void unavailableProviderFailsStartup(){OllamaApi api=mock(OllamaApi.class);when(api.listModels()).thenThrow(new IllegalStateException("offline"));assertThrows(IllegalStateException.class,()->new CharacterModelProvisioner(api,mock(RestClient.class),"storyteller-character","base","system").run(mock(org.springframework.boot.ApplicationArguments.class)));}
 @Test void createFailureFailsStartup(){OllamaApi api=mock(OllamaApi.class);when(api.listModels()).thenReturn(new OllamaApi.ListModelResponse(List.of()));RestClient client=mock(RestClient.class);RestClient.RequestBodyUriSpec request=mock(RestClient.RequestBodyUriSpec.class);RestClient.RequestBodySpec body=mock(RestClient.RequestBodySpec.class);when(client.post()).thenReturn(request);when(request.uri("/api/create")).thenReturn(request);when(request.contentType(any())).thenReturn(request);when(request.body(any(Object.class))).thenReturn(body);when(body.retrieve()).thenThrow(new IllegalStateException("base unavailable"));assertThrows(IllegalStateException.class,()->new CharacterModelProvisioner(api,client,"storyteller-character","base","system").run(mock(org.springframework.boot.ApplicationArguments.class)));}
}
